<script setup>
import {useDramaI18n} from './useDramaI18n.js';
const {language,tr}=useDramaI18n();
import {ref,watch} from 'vue';import {supabase} from '../api/supabase';import {useAccountStore} from '../stores/account';
const account=useAccountStore(),rows=ref([]),error=ref(''),loading=ref(false);let revision=0;
async function load(){const current=++revision;rows.value=[];error.value='';if(!account.user||!supabase)return;loading.value=true;try{const result=await supabase.from('drama_submissions').select('id,kind,payload,status,reply,created_at').eq('owner_id',account.user.id).order('created_at',{ascending:false}).limit(100);if(result.error)throw result.error;if(current===revision)rows.value=result.data;}catch(e){if(current===revision)error.value=e.message;}finally{if(current===revision)loading.value=false;}}
watch(()=>account.user?.id,load,{immediate:true});
</script><template><section v-if="account.user" class="my-drama-submissions"><h3>{{tr('我的剧集投稿与纠错')}}</h3><button @click="load" :disabled="loading">{{tr('刷新审核结果')}}</button><p v-if="error" role="alert">{{error}}</p><p v-else-if="loading">{{tr('正在读取…')}}</p><p v-else-if="!rows.length">{{tr('暂无剧集投稿')}}</p><article v-for="row in rows" :key="row.id"><strong>{{row.kind==='correction'?tr('剧集纠错'):row.payload.titleZh||row.payload.titleEn||row.payload.titleTh}}</strong><span>{{tr({pending:'待审核',approved:'已通过',rejected:'未通过'}[row.status])}}</span><p v-if="row.reply">{{row.reply}}</p></article></section></template><style scoped>.my-drama-submissions{margin-top:28px;border-top:1px solid #8797ab40;padding-top:20px}.my-drama-submissions h3{font-size:15px}.my-drama-submissions button{background:transparent;color:inherit;border:1px solid #8797ab60;border-radius:8px;padding:7px 12px}.my-drama-submissions article{padding:12px 0;border-bottom:1px solid #8797ab30;font-size:13px}.my-drama-submissions span{margin-left:16px;opacity:.7}.my-drama-submissions p{font-size:12px}</style>
